// src/repositories/generatedBundles.ts
async function saveBundle(snapshot) {
  return await sql.begin(async (tx) => {
    const bundles = await tx`
      INSERT INTO generated_bundle (
        public_id, user_id, requested_age, audience_preference, interest, party_type,
        budget_tier_id, bundle_template_id,
        base_retail_price, standard_item_cogs_snapshot,
        status, created_at
      ) VALUES (
        ${snapshot.publicId},
        ${snapshot.userId ?? null},
        ${snapshot.requestedAge},
        ${snapshot.audiencePreference},
        ${snapshot.interest},
        ${snapshot.partyType},
        ${snapshot.budgetTierId},
        ${snapshot.bundleTemplateId},
        ${snapshot.baseRetailPrice},
        ${snapshot.standardItemCogsSnapshot},
        'GENERATED',
        now()
      )
      RETURNING *
    `;
    const bundle = bundles[0];
    if (snapshot.items.length > 0) {
      const itemRows = snapshot.items.map((item) => ({
        generated_bundle_id: bundle.id,
        slot_code: item.slotCode,
        product_id: item.productId,
        product_name_snapshot: item.productNameSnapshot,
        sku_snapshot: item.skuSnapshot,
        cost_snapshot: item.costSnapshot,
        description_snapshot: item.descriptionSnapshot,
        form_factor_snapshot: item.formFactorSnapshot,
        quantity_per_bag: item.quantityPerBag,
        display_order: item.displayOrder
      }));
      await tx`INSERT INTO generated_bundle_item ${tx(itemRows)}`;
    }
    if (snapshot.upgrade) {
      const u = snapshot.upgrade;
      await tx`
        INSERT INTO generated_bundle_upgrade (
          generated_bundle_id,
          standard_product_id, standard_product_name_snapshot,
          standard_sku_snapshot, standard_cost_snapshot,
          standard_retail_adjustment_snapshot,
          product_id, product_name_snapshot,
          sku_snapshot, cost_snapshot,
          retail_price_adjustment_snapshot
        ) VALUES (
          ${bundle.id},
          ${u.standardProductId}, ${u.standardProductNameSnapshot},
          ${u.standardSkuSnapshot}, ${u.standardCostSnapshot},
          ${u.standardRetailAdjustmentSnapshot ?? 0},
          ${u.premiumProductId}, ${u.premiumProductNameSnapshot},
          ${u.premiumSkuSnapshot}, ${u.premiumCostSnapshot},
          ${u.premiumRetailAdjustmentSnapshot ?? 0}
        )
      `;
    }
    if (snapshot.giftBag) {
      const g5 = snapshot.giftBag;
      await tx`
        INSERT INTO generated_bundle_gift_bag (
          generated_bundle_id, gift_bag_option_id,
          name_snapshot, cost_snapshot,
          retail_price_adjustment_snapshot, is_default
        ) VALUES (
          ${bundle.id}, ${g5.giftBagOptionId},
          ${g5.nameSnapshot}, ${g5.costSnapshot},
          ${g5.retailPriceAdjustmentSnapshot}, ${g5.isDefault}
        )
      `;
    }
    return bundle;
  });
}
async function findBundleByPublicId(publicId) {
  const bundles = await sql`
    SELECT gb.*,
           bt.code AS template_code,
           bud.code AS budget_tier_code
    FROM generated_bundle gb
    JOIN bundle_template bt ON bt.id = gb.bundle_template_id
    JOIN budget_tier bud ON bud.id = gb.budget_tier_id
    WHERE gb.public_id = ${publicId}
  `;
  if (bundles.length === 0) return null;
  const bundleRow = bundles[0];
  const [items, upgrades, giftBags] = await Promise.all([
    sql`
      SELECT * FROM generated_bundle_item
      WHERE generated_bundle_id = ${bundleRow.id}
      ORDER BY display_order ASC
    `,
    sql`
      SELECT * FROM generated_bundle_upgrade
      WHERE generated_bundle_id = ${bundleRow.id}
    `,
    sql`
      SELECT gbg.*, gbo.code AS gift_bag_option_code
      FROM generated_bundle_gift_bag gbg
      JOIN gift_bag_option gbo ON gbo.id = gbg.gift_bag_option_id
      WHERE gbg.generated_bundle_id = ${bundleRow.id}
    `
  ]);
  return {
    bundle: bundleRow,
    templateCode: bundleRow.template_code,
    budgetTierCode: bundleRow.budget_tier_code,
    items,
    upgrade: upgrades[0] ?? null,
    giftBag: giftBags[0] ? {
      ...giftBags[0],
      gift_bag_option_code: giftBags[0].gift_bag_option_code
    } : null
  };
}
async function listRecentBundles(limit = 200) {
  return sql`
    SELECT gb.*,
           bt.code AS template_code,
           bud.code AS budget_tier_code
    FROM generated_bundle gb
    JOIN bundle_template bt ON bt.id = gb.bundle_template_id
    JOIN budget_tier bud ON bud.id = gb.budget_tier_id
    ORDER BY gb.created_at DESC
    LIMIT ${limit}
  `;
}

// src/services/generatedBundle.ts
async function getByPublicId(publicId) {
  const agg = await findBundleByPublicId(publicId);
  if (!agg) return null;
  const { bundle, items, upgrade, giftBag, templateCode } = agg;
  return {
    generatedBundleId: bundle.public_id,
    templateCode,
    standardItemCogsSnapshot: parseFloat(bundle.standard_item_cogs_snapshot),
    bundleRetailPrice: bundle.base_retail_price ? parseFloat(bundle.base_retail_price) : 0,
    items: items.map((item) => ({
      slotCode: item.slot_code,
      productName: item.product_name_snapshot,
      sku: item.sku_snapshot,
      description: item.description_snapshot,
      formFactor: item.form_factor_snapshot,
      quantityPerBag: item.quantity_per_bag,
      displayOrder: item.display_order
    })),
    upgrade: upgrade && (upgrade.standard_product_name_snapshot || upgrade.product_name_snapshot) ? {
      standardProductName: upgrade.standard_product_name_snapshot,
      standardSku: upgrade.standard_sku_snapshot,
      standardRetailAdjustment: upgrade.standard_retail_adjustment_snapshot ? parseFloat(upgrade.standard_retail_adjustment_snapshot) : null,
      upgradedProductName: upgrade.product_name_snapshot,
      upgradedSku: upgrade.sku_snapshot,
      upgradedRetailAdjustment: upgrade.retail_price_adjustment_snapshot ? parseFloat(upgrade.retail_price_adjustment_snapshot) : null
    } : null,
    giftBag: giftBag ? {
      code: giftBag.gift_bag_option_code ?? "",
      name: giftBag.name_snapshot,
      retailPriceAdjustment: parseFloat(giftBag.retail_price_adjustment_snapshot),
      isDefault: giftBag.is_default
    } : null
  };
}

// src/services/retailPricing.ts
function computeRetailPrice(cogAdjusted) {
  let price;
  if (cogAdjusted < 1) {
    price = 0.5;
  } else if (cogAdjusted < 4) {
    price = cogAdjusted / 2;
  } else if (cogAdjusted < 10) {
    price = cogAdjusted / 3 + 2 / 3;
  } else {
    price = cogAdjusted * 0.4;
  }
  return Math.round(price * 100) / 100;
}

